(function(E){ const x = E["sales-m1"] = E["sales-m1"] || {units:{}}; x.units["sales-cp-1"] = {"exit":{"id":"c-sales-cp-1-x","course":"sales","unit":"sales-cp-1","type":"exit","items":[{"from":"sales-1-1","kind":"blank","prompt":"The lids seal tightly, which ___ nothing spills in the van.","options":["mean","means","meaning"],"correct":1,"point":2,"why":{"en":"means: 'which' refers to the whole fact, so the verb is singular. 'Mean' is plural; 'meaning' is not a full verb.","tr":"means: 'which' tüm bilgiyi kasteder, fiil tekildir. 'Mean' çoğuldur; 'meaning' tam bir fiil değildir.","fa":"means درست است، چون which به کل آن واقعیت برمی‌گردد و فعلش مفرد است. mean برای جمع است و meaning فعل کامل نیست."}},{"from":"sales-1-1","kind":"mcq","prompt":"Which line is empty sales talk?","options":["We are a world-class leader.","Shelf life: 12 months.","Could I send you a sample?"],"correct":0,"point":1,"why":{"en":"'We are a world-class leader' is a claim nobody can check. Shelf life and a sample offer are real and useful.","tr":"'We are a world-class leader' kimsenin kontrol edemeyeceği bir iddiadır. Raf ömrü ve numune teklifi gerçek ve faydalıdır.","fa":"«We are a world-class leader» ادعایی است که کسی نمی‌تواند بررسی کند. ماندگاری محصول و پیشنهاد نمونه واقعی و مفیدند."}},{"from":"sales-1-3","kind":"mcq","prompt":"Which person can say yes to the purchase?","options":["the decision maker","the sales prospect","the main supplier"],"correct":0,"point":3,"why":{"en":"the decision maker: the person who can approve the purchase. A prospect is a possible buyer; a supplier sells to them.","tr":"the decision maker: satın almayı onaylayabilen kişi. Prospect olası bir alıcıdır; supplier ise onlara satan firmadır.","fa":"the decision maker کسی است که می‌تواند خرید را تأیید کند. prospect یعنی خریدار احتمالی و supplier یعنی کسی که به آن‌ها می‌فروشد."}},{"from":"sales-1-2","kind":"blank","prompt":"Could you tell me who ___ your office supplies?","options":["do buy","is buy","buys"],"correct":2,"point":2,"why":{"en":"buys: 'who' is the subject, so there is no 'do' and the verb takes -s. 'Do buy' and 'is buy' are not English here.","tr":"buys: 'who' öznedir, bu yüzden 'do' gelmez ve fiil -s alır. 'Do buy' ve 'is buy' burada İngilizce değildir.","fa":"buys درست است، چون who خودش فاعل است؛ پس do نمی‌خواهد و فعل ‎-s می‌گیرد. do buy و is buy اینجا انگلیسی نیستند."}},{"from":"sales-1-2","kind":"blank","prompt":"She is in a meeting. Could you put me ___ to her assistant?","options":["through","up","off"],"correct":0,"point":3,"why":{"en":"through: 'put me through to' means connect my call. 'Put me up' means give me a bed; 'put me off' means discourage me.","tr":"through: 'put me through to' telefonu birine bağlamak demektir. 'Put me up' yatacak yer vermek, 'put me off' hevesini kaçırmak demektir.","fa":"through درست است: put me through to یعنی تماسم را به کسی وصل کن. put me up یعنی جای خواب بده و put me off یعنی دلسردم کن."}},{"from":"sales-1-2","kind":"mcq","prompt":"A good first contact starts with ___","options":["one real fact about them.","your full company history.","a discount on the first order."],"correct":0,"point":1,"why":{"en":"One real fact about them shows you did your homework. Your company history is about you, and a discount comes far too early.","tr":"Onlarla ilgili gerçek bir bilgi, araştırma yaptığını gösterir. Şirket tarihin seninle ilgilidir; indirim de çok erken gelir.","fa":"یک واقعیت درباره‌ی خود آن‌ها نشان می‌دهد تحقیق کرده‌ای. تاریخچه‌ی شرکت درباره‌ی خودت است و تخفیف هم خیلی زود است."}},{"from":"sales-1-3","kind":"blank","prompt":"The buyer would like us ___ a price list on Monday.","options":["send","sending","to send"],"correct":2,"point":2,"why":{"en":"to send: would like + person + to + verb. 'Us send' drops to, and 'sending' doesn't follow would like us.","tr":"to send: would like + kişi + to + fiil. 'Us send' to'yu düşürür; 'sending' would like us'tan sonra gelmez.","fa":"to send درست است: would like و بعد شخص و بعد to و فعل. send بدون to غلط است و sending هم بعد از would like us نمی‌آید."}},{"from":"sales-1-3","kind":"mcq","prompt":"Which is the best question after \"Our last supplier was late\"?","options":["Are you sure about that? We hear that often.","What happened in your shops when the goods came late?","Do you know our factory and our range of products?"],"correct":1,"point":1,"why":{"en":"'What happened in your shops when the goods came late?' finds the cost of the problem. Doubting the buyer or talking about your factory loses the chance.","tr":"'What happened in your shops when the goods came late?' sorunun bedelini bulur. Alıcıdan şüphelenmek ya da fabrikanı anlatmak fırsatı kaçırır.","fa":"«What happened in your shops when the goods came late?» هزینه‌ی مشکل را پیدا می‌کند. شک کردن به حرف خریدار یا حرف زدن از کارخانه‌ات فرصت را از بین می‌برد."}}]},"writing":{"id":"c-sales-cp-1-w","course":"sales","unit":"sales-cp-1","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"title":{"en":"Your first three buyers","tr":"İlk üç alıcın","fa":"سه خریدار اول تو"},"prompt":{"en":"Project. List three real buyers you could sell to, or three types of buyer (80-110 words). For each one, write: who they are, one real fact about them, the problem you could solve, who to contact and your first question. Then choose the buyer to contact first, and say why. No product yet? Use saffron tea.","tr":"Proje. Satış yapabileceğin üç gerçek alıcıyı ya da üç alıcı türünü listele (80-110 kelime). Her biri için şunları yaz: kim oldukları, onlarla ilgili gerçek bir bilgi, çözebileceğin sorun, kiminle temas kuracağın ve soracağın ilk soru. Sonra önce hangisiyle temas kuracağını seç ve nedenini söyle. Ürünün yoksa safran çayını kullan.","fa":"پروژه. سه خریدار واقعی که می‌توانی به آن‌ها بفروشی، یا سه نوع خریدار را فهرست کن (۸۰ تا ۱۱۰ کلمه). برای هر کدام بنویس: چه کسانی هستند، یک واقعیت درباره‌ی آن‌ها، مشکلی که می‌توانی حل کنی، با چه کسی تماس می‌گیری و سؤال اولت. بعد انتخاب کن اول با کدام تماس می‌گیری و بگو چرا. محصولی نداری؟ چای زعفرانی را در نظر بگیر."},"model":"1. A food chain in Poland, 40 shops. No saffron tea on its website. Problem: few gift products for winter. Contact: the head buyer. First question: What sells best in December?\n\n2. A restaurant group in Oman. It opened two places this year. Problem: small local supply. Contact: procurement. First question: Who supplies your tea now?\n\n3. An online tea shop in Germany. Its reviews ask for stronger tea. Problem: no strong blend. Contact: the owner. First question: What do customers ask for?\n\nFirst: the online shop, because the owner decides alone.","frame":"1. ___. Fact: ___. Problem: ___. Contact: ___. First question: ___?\n\n2. ___. Fact: ___. Problem: ___. Contact: ___. First question: ___?\n\n3. ___. Fact: ___. Problem: ___. Contact: ___. First question: ___?\n\nFirst: ___, because ___.","words":[{"word":"Problem"},{"word":"Contact"},{"word":"First question"}],"minWords":70,"minSentences":5,"rubric":["Task done: three buyers, each with a fact, a problem, a contact and a question","Organised: same order for each buyer; one clear first choice","Language: polite questions in statement order; which means and so + can; would like us to + verb","Tone: real facts, not guesses"],"rubricI18n":{"tr":["Görev: üç alıcı; her birinde bilgi, sorun, kişi ve soru","Düzen: her alıcıda aynı sıra; net bir ilk seçim","Dil: düz cümle sırasında kibar sorular; which means ve so + can; would like us to + fiil","Üslup: tahmin değil, gerçek bilgiler"],"fa":["کامل بودن کار: سه خریدار، هر کدام با واقعیت، مشکل، مخاطب و سؤال","نظم: برای هر خریدار همان ترتیب؛ یک انتخاب اول روشن","زبان: سؤال‌های مؤدبانه با ترتیب جمله‌ی خبری، و درست به کار بردن which means، so you can و would like us to","لحن: واقعیت، نه حدس"]}},"speaking":{"id":"sales-cp-1","course":"sales","unit":"sales-cp-1","topic":{"en":"Your call to the first buyer","tr":"İlk alıcına araman","fa":"تماس تو با خریدار اول"},"warmup":{"en":"Say your first sentence aloud three times, until it sounds natural.","tr":"İlk cümleni doğal gelene kadar üç kez yüksek sesle söyle.","fa":"جمله‌ی اولت را سه بار بلند بگو تا طبیعی شود."},"questions":[{"en":"Reach the right person: say who you are and why, and ask who buys your product.","tr":"Doğru kişiye ulaş: kim olduğunu ve nedenini söyle, ürününü kimin aldığını sor.","fa":"خودت را به مسئول خرید برسان: بگو چه کسی هستی و چرا تماس گرفته‌ای و بپرس چه کسی محصولت را می‌خرد."},{"en":"Give your 30-second pitch, then ask two questions about their needs.","tr":"30 saniyelik tanıtımını yap, sonra ihtiyaçlarıyla ilgili iki soru sor.","fa":"معرفی ۳۰ ثانیه‌ای‌ات را بگو، بعد دو سؤال درباره‌ی نیازشان بپرس."},{"en":"Summarise what you heard, and agree one small next step.","tr":"Duyduğunu özetle ve küçük bir sonraki adımda anlaş.","fa":"چیزی را که شنیدی خلاصه کن و روی یک قدم بعدی کوچک توافق کن."}],"followups":[{"en":"Now really make this call, or send the email, this week.","tr":"Şimdi bu aramayı gerçekten yap ya da e-postayı bu hafta gönder.","fa":"حالا این هفته واقعاً این تماس را بگیر یا ایمیل را بفرست."}],"expressions":[{"phrase":"The reason I am calling is ...","meaning":{"en":"Gives the reason early.","tr":"Nedeni baştan söyler.","fa":"دلیل را زود می‌گوید."}},{"phrase":"So you would like us to ...","meaning":{"en":"Summarises the need.","tr":"İhtiyacı özetler.","fa":"نیاز را خلاصه می‌کند."}},{"phrase":"Could I send you ...?","meaning":{"en":"Asks for one small step.","tr":"Küçük bir adım ister.","fa":"یک قدم کوچک می‌خواهد."}}],"model":"Good morning. The reason I am calling is that your website shows no saffron tea. Could you tell me who is in charge of buying tea? ... We pack saffron tea in Mashhad for small shops. What sells best in December? ... What happens when gift products run out? ... So you would like a winter gift before December, is that right? ... Could I send you ten sample boxes?","selfCheck":[{"en":"I gave my reason early.","tr":"Nedenimi erken söyledim.","fa":"دلیلم را زود گفتم."},{"en":"I asked about their needs before I offered a sample.","tr":"Numune önermeden önce ihtiyaçlarını sordum.","fa":"قبل از پیشنهاد نمونه، درباره‌ی نیازشان سؤال کردم."},{"en":"I summarised.","tr":"Özetledim.","fa":"خلاصه کردم."},{"en":"I asked for one small step.","tr":"Küçük bir adım istedim.","fa":"یک قدم کوچک خواستم."}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
